"""Week 4, Day 7: evaluate one run from declared observable facts."""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path

from .loop import AgentRun
from .protocol import AgentError, ToolAction
from .receipts import ReceiptStore
from .workspace import Workspace


def _expect_text(value: object, name: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{name} must not be blank")
    return value


def _expect_path(value: object, name: str) -> str:
    path = Path(_expect_text(value, name))
    if (
        path.is_absolute()
        or path == Path(".")
        or ".." in path.parts
        or "\0" in str(path)
    ):
        raise ValueError(f"{name} must be a relative file path")
    return str(path)


@dataclass(frozen=True)
class FileExpectation:
    """One exact UTF-8 file fact expected after the run."""

    path: str
    content: str

    def __post_init__(self) -> None:
        object.__setattr__(self, "path", _expect_path(self.path, "file path"))
        if not isinstance(self.content, str):
            raise ValueError("file content must be a string")


@dataclass(frozen=True)
class ResultExpectation:
    """One required substring in an observable tool result."""

    tool: str
    contains: str

    def __post_init__(self) -> None:
        _expect_text(self.tool, "result tool")
        _expect_text(self.contains, "result substring")


@dataclass(frozen=True)
class ReceiptExpectation:
    """Declared facts for one named durable effect receipt."""

    tool_call_id: str
    tool: str
    exit_state: str
    result_contains: str
    changed_artifacts: tuple[str, ...] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        _expect_text(self.tool_call_id, "receipt call id")
        _expect_text(self.tool, "receipt tool")
        if self.exit_state not in {"ok", "error"}:
            raise ValueError("receipt exit_state must be 'ok' or 'error'")
        _expect_text(self.result_contains, "receipt result substring")
        if not isinstance(self.changed_artifacts, tuple):
            raise ValueError("receipt changed_artifacts must be a tuple")
        object.__setattr__(
            self,
            "changed_artifacts",
            tuple(
                _expect_path(artifact, "changed artifact")
                for artifact in self.changed_artifacts
            ),
        )


@dataclass(frozen=True)
class EvaluationCase:
    """The observable facts one deterministic course case requires."""

    final_contains: str
    files: tuple[FileExpectation, ...] = field(default_factory=tuple)
    results: tuple[ResultExpectation, ...] = field(default_factory=tuple)
    receipts: tuple[ReceiptExpectation, ...] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        self._validate()

    def _validate(self) -> None:
        _expect_text(self.final_contains, "final substring")
        groups = (
            (self.files, FileExpectation, "files"),
            (self.results, ResultExpectation, "results"),
            (self.receipts, ReceiptExpectation, "receipts"),
        )
        for values, expected_type, name in groups:
            if not isinstance(values, tuple) or any(
                not isinstance(value, expected_type) for value in values
            ):
                raise ValueError(f"evaluation {name} must be a tuple of expectations")
        file_paths = [expected.path for expected in self.files]
        if len(file_paths) != len(set(file_paths)):
            raise ValueError("evaluation file paths must be unique")
        call_ids = [expected.tool_call_id for expected in self.receipts]
        if len(call_ids) != len(set(call_ids)):
            raise ValueError("evaluation receipt call ids must be unique")


@dataclass(frozen=True)
class EvaluationCheck:
    """One named PASS/FAIL result backed by an observable fact."""

    name: str
    passed: bool
    detail: str


@dataclass(frozen=True)
class EvaluationReport:
    """Stable ordered checks for one evaluation case."""

    checks: tuple[EvaluationCheck, ...]

    @property
    def passed(self) -> bool:
        return bool(self.checks) and all(check.passed for check in self.checks)

    def render(self) -> str:
        lines = [f"evaluation: {'PASS' if self.passed else 'FAIL'}"]
        for check in self.checks:
            status = "PASS" if check.passed else "FAIL"
            lines.append(f"- {check.name}: {status} ({check.detail})")
        return "\n".join(lines)


def _file_check(workspace: Workspace, expected: FileExpectation) -> EvaluationCheck:
    name = f"file:{expected.path}"
    try:
        observed = workspace.resolve_path(expected.path).read_text(encoding="utf-8")
    except (AgentError, OSError, UnicodeError) as error:
        return EvaluationCheck(name, False, f"evidence unavailable: {error}")
    if observed == expected.content:
        return EvaluationCheck(name, True, "content matches")
    return EvaluationCheck(name, False, "content does not match")


def _result_check(run: AgentRun, expected: ResultExpectation) -> EvaluationCheck:
    name = f"result:{expected.tool}"
    matched = any(
        isinstance(event.action, ToolAction)
        and event.action.tool == expected.tool
        and isinstance(event.result, str)
        and expected.contains in event.result
        for event in run.events
    )
    detail = "required result observed" if matched else "required result not observed"
    return EvaluationCheck(name, matched, detail)


def _receipt_reader(receipts: ReceiptStore) -> tuple[ReceiptStore | None, str | None]:
    if receipts.path is None:
        return receipts, None
    try:
        return ReceiptStore(receipts.path), None
    except (AgentError, OSError, UnicodeError) as error:
        return None, f"receipt evidence unavailable: {error}"


def _receipt_check(
    receipts: ReceiptStore | None,
    load_error: str | None,
    expected: ReceiptExpectation,
) -> EvaluationCheck:
    name = f"receipt:{expected.tool_call_id}"
    if load_error is not None:
        return EvaluationCheck(name, False, load_error)
    assert receipts is not None
    try:
        receipt = receipts.get(expected.tool_call_id)
    except (AgentError, OSError) as error:
        return EvaluationCheck(name, False, f"receipt lookup failed: {error}")
    if receipt is None:
        return EvaluationCheck(name, False, "receipt is absent")
    matched = (
        receipt.tool == expected.tool
        and receipt.exit_state == expected.exit_state
        and expected.result_contains in receipt.result
        and receipt.changed_artifacts == expected.changed_artifacts
    )
    detail = "receipt facts match" if matched else "receipt facts do not match"
    return EvaluationCheck(name, matched, detail)


def evaluate_run(
    run: AgentRun,
    workspace: Workspace,
    receipts: ReceiptStore,
    case: EvaluationCase,
) -> EvaluationReport:
    """Judge one run only from the observable facts declared by ``case``."""

    if not isinstance(run, AgentRun):
        raise ValueError("run must be an AgentRun")
    if not isinstance(workspace, Workspace):
        raise ValueError("workspace must be a Workspace")
    if not isinstance(receipts, ReceiptStore):
        raise ValueError("receipts must be a ReceiptStore")
    if not isinstance(case, EvaluationCase):
        raise ValueError("case must be an EvaluationCase")
    case._validate()

    final_ok = (
        run.completed and run.final is not None and case.final_contains in run.final
    )
    checks = [
        EvaluationCheck(
            "final",
            final_ok,
            "required final observed" if final_ok else "required final not observed",
        )
    ]
    checks.extend(_file_check(workspace, expected) for expected in case.files)
    checks.extend(_result_check(run, expected) for expected in case.results)
    receipt_reader, load_error = _receipt_reader(receipts)
    checks.extend(
        _receipt_check(receipt_reader, load_error, expected)
        for expected in case.receipts
    )
    return EvaluationReport(tuple(checks))
